/*
 * A041196  Numerators of continued fraction convergents to sqrt(109).
 * https://oeis.org/A041196
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the n-th convergent of sqrt(109) (indexing
 *            starts at a(0) = 10). Convergents are generated by the
 *            recurrence p_{-1} = 1, p_0 = 10, p_k = a_k * p_{k-1} + p_{k-2},
 *            with periodic partial quotients a_k of sqrt(109): a_1..a_15 =
 *            2,3,1,2,4,1,6,6,1,4,2,1,3,2,20 (period 15)
 * Range:     u8 n <= 3, u16 n <= 8, u32 n <= 18, u64 n <= 37, u128 n <= 78,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* partial quotients of sqrt(109) after the initial term */
    static const seq_t PERIOD[] = {
        (seq_t)2, (seq_t)3, (seq_t)1, (seq_t)2, (seq_t)4,
        (seq_t)1, (seq_t)6, (seq_t)6, (seq_t)1, (seq_t)4,
        (seq_t)2, (seq_t)1, (seq_t)3, (seq_t)2, (seq_t)20
    };
    static const idx_t L = sizeof(PERIOD) / sizeof(PERIOD[0]);

    seq_t prevprev = 1;   /* p_{-1} */
    seq_t prev     = 10;  /* p_0 (a(0)) */

    for (idx_t i = 1; i <= n; ++i) {
        seq_t a_k = PERIOD[(i - 1) % L];
        seq_t cur = a_k * prev + prevprev;
        prevprev = prev;
        prev     = cur;
    }
    return prev;
}
